from thefuck.utils import replace_argument
from thefuck.specific.git import git_support


@git_support
def match(cmd):
    rejected_err = '! [rejected]' in cmd.stderr
    push_in_script = 'push' in cmd.script
    refs_err = 'failed to push some refs to' in cmd.stderr
    behind_err = 'Updates were rejected because the tip of your current branch is behind' in cmd.stderr
    return push_in_script and rejected_err and refs_err and behind_err


@git_support
def get_new_command(cmd):
    return replace_argument(cmd.script, 'push', 'push --force')


